// ---------------------------------------------------------------------------
// generate-audio.mjs — creates public/media/audio/demo-track.wav
//
// An ORIGINAL, softly synthesized ambient loop for the demo music control.
// Deterministic (no randomness): a warm D-major pad with slow tremolo and
// sparse pentatonic plucks. Because it is generated by this script, the
// project holds full rights to it — see public/media/ATTRIBUTION.md.
//
// Run: node scripts/generate-audio.mjs
// ---------------------------------------------------------------------------
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

// 16 kHz mono is deliberate: the content is a warm pad whose highest
// partial sits near 3 kHz, so 8 kHz Nyquist is ample, and it keeps the
// loop ~25% smaller than 22.05 kHz (≈640 KB vs 861 KB) with no encoder
// dependency. Change this and re-run the script to regenerate.
const SAMPLE_RATE = 16000;
const DURATION_SECONDS = 20;
const TOTAL = SAMPLE_RATE * DURATION_SECONDS;

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const outPath = join(root, "public", "media", "audio", "demo-track.wav");

const mix = new Float64Array(TOTAL);

// --- Warm pad: D-major stack, two detuned sines per voice, slow tremolo ----
const padVoices = [
  { f: 146.83, a: 0.1 }, // D3
  { f: 220.0, a: 0.075 }, // A3
  { f: 293.66, a: 0.06 }, // D4
  { f: 369.99, a: 0.045 }, // F#4
];

for (const [index, voice] of padVoices.entries()) {
  const phase = index * 1.3;
  for (let i = 0; i < TOTAL; i++) {
    const t = i / SAMPLE_RATE;
    const tremolo = 1 + 0.15 * Math.sin(2 * Math.PI * 0.08 * t + phase);
    const value =
      0.6 * Math.sin(2 * Math.PI * voice.f * t) +
      0.4 * Math.sin(2 * Math.PI * voice.f * 1.003 * t);
    mix[i] += voice.a * tremolo * value;
  }
}

// --- Sparse bell plucks (D major pentatonic) ------------------------------
const NOTES = {
  D5: 587.33,
  E5: 659.26,
  Fs5: 739.99,
  A5: 880.0,
  B5: 987.77,
  D6: 1174.66,
};

const pluckPattern = [
  [0.4, NOTES.A5],
  [1.9, NOTES.Fs5],
  [3.1, NOTES.D5],
  [4.6, NOTES.E5],
  [6.2, NOTES.A5],
  [7.4, NOTES.D6],
  [8.9, NOTES.B5],
  [10.4, NOTES.Fs5],
  [11.6, NOTES.A5],
  [13.1, NOTES.E5],
  [14.6, NOTES.D5],
  [15.8, NOTES.Fs5],
  [17.3, NOTES.A5],
  [18.6, NOTES.D5],
];

const PLUCK_AMP = 0.17;
const PLUCK_LENGTH_SECONDS = 4;

for (const [startSeconds, freq] of pluckPattern) {
  const start = Math.floor(startSeconds * SAMPLE_RATE);
  const end = Math.min(TOTAL, start + PLUCK_LENGTH_SECONDS * SAMPLE_RATE);
  for (let i = start; i < end; i++) {
    const t = (i - start) / SAMPLE_RATE;
    const attack = Math.min(1, t / 0.012);
    const envelope = attack * Math.exp(-t / 1.15);
    const tone =
      Math.sin(2 * Math.PI * freq * t) +
      0.3 * Math.sin(2 * Math.PI * freq * 2 * t) +
      0.1 * Math.sin(2 * Math.PI * freq * 3.01 * t);
    mix[i] += PLUCK_AMP * envelope * tone;
  }
}

// --- Master: normalize, gentle loop fades, 16-bit PCM ---------------------
let peak = 0;
for (let i = 0; i < TOTAL; i++) peak = Math.max(peak, Math.abs(mix[i]));
const scale = peak > 0 ? 0.82 / peak : 1;

const FADE_IN = Math.floor(0.4 * SAMPLE_RATE);
const FADE_OUT = Math.floor(0.8 * SAMPLE_RATE);

const pcm = Buffer.alloc(TOTAL * 2);
for (let i = 0; i < TOTAL; i++) {
  let gain = scale;
  if (i < FADE_IN) gain *= i / FADE_IN;
  if (i > TOTAL - FADE_OUT) gain *= (TOTAL - i) / FADE_OUT;
  const value = Math.max(-1, Math.min(1, mix[i] * gain));
  pcm.writeInt16LE(Math.round(value * 32767), i * 2);
}

// --- WAV container ---------------------------------------------------------
const header = Buffer.alloc(44);
header.write("RIFF", 0);
header.writeUInt32LE(36 + pcm.length, 4);
header.write("WAVE", 8);
header.write("fmt ", 12);
header.writeUInt32LE(16, 16); // PCM chunk size
header.writeUInt16LE(1, 20); // PCM format
header.writeUInt16LE(1, 22); // mono
header.writeUInt32LE(SAMPLE_RATE, 24);
header.writeUInt32LE(SAMPLE_RATE * 2, 28); // byte rate
header.writeUInt16LE(2, 32); // block align
header.writeUInt16LE(16, 34); // bits per sample
header.write("data", 36);
header.writeUInt32LE(pcm.length, 40);

mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, Buffer.concat([header, pcm]));

console.log(
  `Wrote ${outPath} (${(44 + pcm.length) / 1024 | 0} KB, ${DURATION_SECONDS}s, original synthesized loop)`,
);
